// How round sample scores are, and the check that holds a run to it
// (scripts/seed/round-scores.ts). The datasets are the test fixture's,
// generated by the real generator.
import { describe, expect, it } from "vitest";
import { small, SMALL } from "./fixture";
import { roundScoreCheck, roundShares, MAX_ROUND_SCORE_PCT, MIN_ROUND_SCORE_SAMPLE, SCORE_KINDS } from "../../scripts/seed/round-scores";
import { SCORE_RULE_2_FROM } from "../../scripts/seed/verdicts";

const AFTER = "2026-11-20T00:00:00.000Z";
const verdictsOf = (ds: ReturnType<typeof small>) => ds.debates.map((d) => d.row.verdict as never);

describe("rule 2 across a whole run", () => {
  // A run begun after the cutover: every verdict follows rule 2.
  const fresh = small({ baseTo: AFTER, to: AFTER });

  it("lands on a multiple of 5 well under the limit, for the composite and each criterion", () => {
    const s = roundShares(verdictsOf(fresh));
    expect(s.n).toBeGreaterThan(MIN_ROUND_SCORE_SAMPLE);
    for (const k of SCORE_KINDS) expect(s.pct[k], k).toBeLessThan(16.5);
    expect(s.pct.score).toBeLessThan(15);
  });

  it("gives whole-number criteria and spreads the composite, with no value standing out", () => {
    const scored = fresh.debates.map((d) => d.row.verdict).filter((v) => !v.rejected) as { score: number; fidelity: number; rigor: number; engagement: number }[];
    for (const v of scored) for (const k of ["fidelity", "rigor", "engagement"] as const) expect(Number.isInteger(v[k])).toBe(true);
    const counts = new Map<number, number>();
    for (const v of scored) counts.set(v.score, (counts.get(v.score) ?? 0) + 1);
    // No single composite takes more than 4% of verdicts, and at least 60
    // different composites occur.
    expect(Math.max(...counts.values()) / scored.length).toBeLessThan(0.04);
    expect(counts.size).toBeGreaterThan(60);
  });

  it("passes the check", () => {
    const c = roundScoreCheck(fresh);
    expect(c.ok, c.detail).toBe(true);
    expect(c.detail).not.toMatch(/too few/);
  });
});

describe("a run begun before the cutover", () => {
  it("keeps rule 1 for every row dated before it, and the rows themselves", () => {
    const cut = Date.parse(SCORE_RULE_2_FROM);
    const until = small({ to: "2026-11-05T23:00:00.000Z" });
    const past = small({ to: "2026-11-08T00:00:00.000Z" });
    const before = (ds: ReturnType<typeof small>) => ds.debates.filter((d) => Date.parse(d.row.created_at) < cut).map((d) => d.row);
    expect(before(past)).toEqual(before(until));
    for (const d of past.debates) {
      if (d.row.verdict.rejected) continue;
      expect(d.row.verdict.prompt_version).toBe(Date.parse(d.row.created_at) < cut ? "sample-template-1" : "sample-template-2");
    }
  });

  it("reports rule 1's share without judging it, and judges nothing while rule 2 has few verdicts", () => {
    const c = roundScoreCheck(small({ to: "2026-11-08T00:00:00.000Z" }));
    expect(c.ok).toBe(true);
    expect(c.detail).toMatch(/too few to judge/);
    expect(c.detail).toMatch(/rule 1, not judged: \d+ verdicts, score [\d.]+%/);
    expect(SMALL.baseTo < SCORE_RULE_2_FROM).toBe(true);
  });
});

describe("the check", () => {
  const verdict = (score: number, f = 7, r = 6, e = 4) => ({
    cohort: 0,
    row: { verdict: { rejected: false, prompt_version: "sample-template-2", score, fidelity: f, rigor: r, engagement: e } },
  });
  const ds = (scores: number[]) => ({ debates: scores.map((s) => verdict(s)) as never });

  it(`fails a run whose composites are more than ${MAX_ROUND_SCORE_PCT}% multiples of 5`, () => {
    // 25% round: 70, 75, 80 and 85 among a spread of other values.
    const scores = Array.from({ length: 1200 }, (_, i) => (i % 4 === 0 ? 70 + 5 * (i % 16 === 0 ? 0 : (i / 4) % 4) : 61 + (i % 4) * 6));
    const c = roundScoreCheck(ds(scores));
    expect(c.ok).toBe(false);
    expect(c.detail).toMatch(/over 20%: score/);
  });

  it("fails on a criterion alone", () => {
    const rows = Array.from({ length: 1200 }, (_, i) => verdict(61 + (i % 4) * 6, 7, i % 3 === 0 ? 5 : 6));
    const c = roundScoreCheck({ debates: rows as never });
    expect(c.ok).toBe(false);
    expect(c.detail).toMatch(/over 20%: rigor$/);
  });

  it("passes at the limit and counts only the rows in scope", () => {
    const at = Array.from({ length: 1000 }, (_, i) => (i % 5 === 0 ? 70 : 71));
    expect(roundScoreCheck(ds(at)).ok).toBe(true);
    const rows = at.map((s, i) => ({ ...verdict(s), cohort: i < 10 ? 0 : 5 }));
    expect(roundScoreCheck({ debates: rows as never }, { cohortLimit: 1, min: 1 }).detail).toMatch(/rule 2: 10 verdicts/);
  });

  it("leaves out rejections", () => {
    const rows = [{ cohort: 0, row: { verdict: { rejected: true, prompt_version: "sample-template-1" } } }];
    expect(roundShares(rows.map((r) => r.row.verdict) as never).n).toBe(0);
  });
});
